style.css:
@-moz-document domain("youtube.com") {
/* 1. HIDE THE DEFAULT SYSTEM RED SPINNER PARTS */
    .ytp-spinner-container {
        border-color: transparent !important;
    }
    
    /* 2. INJECT THE PASTEL GLOWING ANIMATION WHEEL */
    .ytp-spinner-rotator {
        /* Soft magical spinning ring border gradient colors */
        border-color: #ce67b6 transparent #cda3f6 transparent !important;
        border-style: solid !important;
        border-width: 4px !important;
        
        /* Subtle glowing aura matching your text-shadow effects */
        filter: drop-shadow(0px 0px 4px #ffffff) !important;
        
        /* Continuous clean rotation tracking standard spinner rates */
        animation: ytp-spinner-rotate 0.8s linear infinite !important;
    }
}
